<?php require __DIR__.'/../includes/functions.php'; if(!empty($_SESSION['admin_id'])){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$pdo->prepare('SELECT * FROM admins WHERE username=?');$st->execute([$_POST['username']??'']);$a=$st->fetch(); if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_user']=$a['username'];header('Location:index.php');exit;} $err='Username or password is incorrect.';} ?><!doctype html><html><head><meta charset="utf-8"><title>Admin Login</title><link rel="stylesheet" href="admin.css"></head><body class="login"><form method="post"><h1>Admin panel</h1><p>Salamlar</p><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><input name="username" placeholder="Username" required><input name="password" type="password" placeholder="Password" required><button>Login</button></form></body></html>
